// ==============================================================================
// N8N NODE: Formatear Reporte Periódico de Estado y Clima (LoRa Mesh)
// Ubicación: Lehigh Acres, FL (Disparo cada 6h: 00:00, 06:00, 12:00, 18:00 UTC)
// ==============================================================================
// CONTRATO DE INTERFAZ:
// - Entrada: Respuesta JSON de API Open-Meteo (current weather).
// - Salida: Payload estandarizado para publicación en 'meshcore/tx'.
// - Regla de Airtime LoRa: Mensaje ultracompacto (< 200 bytes) para Spreading
//   Factor alto (SF11/SF12) sin saturar el ciclo de trabajo del transceptor.
// ==============================================================================

const WMO_CODES = {
  0: '☀️ Despejado',
  1: '🌤️ Mayormente despejado',
  2: '⛅ Parcialmente nublado',
  3: '☁️ Nublado',
  45: '🌫️ Niebla',
  48: '🌫️ Niebla con escarcha',
  51: '🌦️ Llovizna ligera',
  53: '🌦️ Llovizna moderada',
  55: '🌦️ Llovizna densa',
  56: '🌧️ Llovizna helada ligera',
  57: '🌧️ Llovizna helada densa',
  61: '🌧️ Lluvia ligera',
  63: '🌧️ Lluvia moderada',
  65: '🌧️ Lluvia fuerte',
  66: '🌧️ Lluvia helada ligera',
  67: '🌧️ Lluvia helada fuerte',
  71: '❄️ Nieve ligera',
  73: '❄️ Nieve moderada',
  75: '❄️ Nieve intensa',
  77: '❄️ Granos de nieve',
  80: '🌧️ Chubascos ligeros',
  81: '🌧️ Chubascos moderados',
  82: '🌧️ Chubascos violentos',
  85: '🌨️ Chubascos de nieve ligeros',
  86: '🌨️ Chubascos de nieve intensos',
  95: '⛈️ Tormenta eléctrica',
  96: '⛈️ Tormenta con granizo ligero',
  99: '⛈️ Tormenta con granizo fuerte'
};

const results = [];

for (const item of $input.all()) {
  const data = item.json || {};
  const current = data.current || {};

  // 1. Extracción y conversión de métricas meteorológicas
  const tempC = current.temperature_2m !== undefined ? Number(current.temperature_2m) : 25.0;
  const tempF = Math.round(((tempC * 9 / 5) + 32) * 10) / 10;
  const feelsLikeC = current.apparent_temperature !== undefined ? Number(current.apparent_temperature) : tempC;
  const feelsLikeF = Math.round(((feelsLikeC * 9 / 5) + 32) * 10) / 10;
  const humidity = current.relative_humidity_2m !== undefined ? Math.round(current.relative_humidity_2m) : 60;
  const windKmh = current.wind_speed_10m !== undefined ? Number(current.wind_speed_10m) : 10.0;
  const windMph = Math.round((windKmh * 0.621371) * 10) / 10;
  const weatherCode = current.weather_code !== undefined ? Number(current.weather_code) : 0;
  const weatherDesc = WMO_CODES[weatherCode] || '🌤️ Variable';
  const precip = current.precipitation !== undefined ? Number(current.precipitation) : 0;

  // 2. Estampas temporales (Local Lehigh Acres America/New_York y UTC)
  const now = new Date();
  const localTimeStr = now.toLocaleString('es-US', {
    timeZone: 'America/New_York',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false
  });
  const utcHourStr = now.toISOString().substring(11, 16);

  // 3. Ensamblado de texto formateado LoRa (Airtime-Friendly, ultra-compacto < 120B para canal LoRa)
  let statusText = `[Clima Lehigh] ${tempC}°C (ST ${feelsLikeC}°C) | Hum:${humidity}% | Vnt:${windKmh}km/h | ${weatherDesc}`;
  if (precip > 0) {
    statusText += ` | Prec:${precip}mm`;
  }
  statusText += ` (${utcHourStr}Z)`;

  // 4. Payload canónico para MeshCore Bridge v3.0 (tópico meshcore/tx)
  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_periodic_${Date.now()}`,
      target: 'broadcast',
      to: 'broadcast',
      channel_index: 0,
      channel_idx: 0,
      text: statusText,
      metadata: {
        location: 'Lehigh Acres, FL',
        coordinates: {
          latitude: 26.6254,
          longitude: -81.6248
        },
        temperature_c: tempC,
        temperature_f: tempF,
        humidity_pct: humidity,
        wind_kmh: windKmh,
        weather_code: weatherCode,
        weather_desc: weatherDesc,
        precip_mm: precip,
        timestamp: now.toISOString()
      }
    }
  });
}

return results;

// ==============================================================================
// N8N NODE: Validación, Normalización y Deduplicación de Paquetes MeshCore (v3.0)
// ==============================================================================
// CONTRATO Y REGLAS DE PROTOCOLO:
// 1. SSoT MeshCore: Clasifica roles canónicos ('CLIENT', 'REPEATER', 'ROOM', 'SENSOR').
// 2. Prohibición de Bucle Local: Ignora paquetes propios (is_outgoing, is_local, sender='local').
// 3. Supresión de Bucles de Bots: Ignora mensajes con prefijos de respuesta automática ([Eco, [Status, etc.).
// 4. Deduplicación en Memoria: Ventana deslizante de 30s por hash (eventType + sender + channel + text).
// 5. Compatibilidad de Desempaquetado: Acepta JSON anidado en 'message', 'data' o directo en raíz.
// ==============================================================================

const staticData = $getWorkflowStaticData('global');
if (!staticData.messageCache) {
  staticData.messageCache = {};
}

const now = Date.now();
const CACHE_TTL_MS = 30000; // Ventana de 30 segundos

// Limpieza periódica de entradas vencidas (> 60s)
for (const key of Object.keys(staticData.messageCache)) {
  if (now - staticData.messageCache[key] > 60000) {
    delete staticData.messageCache[key];
  }
}

const results = [];

for (const item of $input.all()) {
  let payload = item.json;

  // 1. Desempaquetar si el broker MQTT o n8n encapsuló el JSON en string
  if (payload && payload.message !== undefined) {
    if (typeof payload.message === 'string') {
      try {
        payload = JSON.parse(payload.message);
      } catch (e) {
        payload = { text: payload.message, event_type: 'public' };
      }
    } else if (typeof payload.message === 'object' && payload.message !== null) {
      payload = payload.message;
    }
  } else if (payload && payload.data !== undefined) {
    if (typeof payload.data === 'string') {
      try {
        payload = JSON.parse(payload.data);
      } catch (e) {
        payload = { text: payload.data, event_type: 'public' };
      }
    } else if (typeof payload.data === 'object' && payload.data !== null) {
      payload = payload.data;
    }
  }

  if (!payload || typeof payload !== 'object') {
    continue;
  }

  // 2. Extraer remitente canónico (Clave pública hex o ID)
  const senderId = String(
    payload.sender ||
    payload.public_key ||
    payload.pubkey ||
    payload.from ||
    payload.sender_id ||
    'unknown'
  ).trim();

  // 3. Extraer rol del nodo según estándar oficial MeshCore (SSoT FirmwareAdvertType)
  let role = String(payload.role || '').toUpperCase();
  if (!role) {
    const advType = Number(payload.adv_type !== undefined ? payload.adv_type : (payload.type !== undefined ? payload.type : -1));
    if (advType === 2 || payload.is_repeater === true) {
      role = 'REPEATER';
    } else if (advType === 3) {
      role = 'ROOM';
    } else if (advType === 4) {
      role = 'SENSOR';
    } else if (advType === 0 || advType === 1) {
      role = 'CLIENT';
    } else if (payload.temperature_c !== undefined || payload.humidity_pct !== undefined) {
      role = 'SENSOR';
    } else {
      role = 'CLIENT';
    }
  }

  // 4. Regla SSoT 1.2: Filtrar paquetes locales y salientes para prevenir bucles infinitos
  const isLocalSender = Boolean(
    payload.is_outgoing === true ||
    payload.is_local === true ||
    role === 'LOCAL' ||
    senderId.toLowerCase() === 'local'
  );
  if (isLocalSender) {
    continue;
  }

  // 5. Determinar tipo de evento canónico
  let eventType = payload.event_type || payload.type || 'public';
  if (eventType === 'repeater_response' || eventType === 'repeater_telemetry') {
    eventType = 'repeater_response';
  } else if (
    eventType === 'telemetry' ||
    payload.temperature_c !== undefined ||
    payload.battery_pct !== undefined ||
    payload.voltage_v !== undefined
  ) {
    if (!payload.text) {
      eventType = 'telemetry';
    }
  } else if (eventType === 'node_advert' || eventType === 'node_discovered' || eventType === 'contact_updated') {
    eventType = 'node_advert';
  } else if (eventType === 'rf_log' || eventType === 'log_data') {
    eventType = 'rf_log';
  }

  const senderName = String(payload.sender_name || payload.adv_name || payload.name || payload.alias || senderId).trim();
  const channelIdx = Number(payload.channel_index !== undefined ? payload.channel_index : (payload.channel_idx !== undefined ? payload.channel_idx : 0));
  const text = String(payload.text || payload.raw_text || payload.message || '').trim();

  // 6. Si no hay contenido textual y no es evento especial, descartar
  if (!text && eventType !== 'telemetry' && eventType !== 'node_advert' && eventType !== 'rf_log' && eventType !== 'repeater_response') {
    continue;
  }

  // 7. Supresión de bucles de bots: ignorar ecos propios y mensajes de bot conocidos
  if (
    text.startsWith('[Eco ') ||
    text.startsWith('[Status ') ||
    text.startsWith('[ACK') ||
    text.startsWith('📡 ') ||
    text.startsWith('⛔ ') ||
    text.startsWith('📖 ') ||
    text.startsWith('⏰ ') ||
    text.startsWith('📅 ') ||
    text.startsWith('🏓 ')
  ) {
    continue;
  }

  // 8. Deduplicación determinista por ventana de 30 segundos
  const msgKey = `${eventType}_${senderId}_${channelIdx}_${text}`;
  let isDuplicate = false;
  if (text.length > 0) {
    if (staticData.messageCache[msgKey] && (now - staticData.messageCache[msgKey] < CACHE_TTL_MS)) {
      isDuplicate = true;
    } else {
      staticData.messageCache[msgKey] = now;
    }
  }

  results.push({
    json: {
      ...payload,
      event_type: eventType,
      sender: senderId,
      sender_id: senderId,
      sender_name: senderName,
      role: role,
      channel_index: channelIdx,
      channel_idx: channelIdx,
      text: text,
      is_duplicate: isDuplicate,
      processed_at: new Date().toISOString()
    }
  });
}

return results;

// ==============================================================================
// N8N NODE: Procesador de Canal Público (Canal 0 / Broadcast)
// ==============================================================================
// CONTRATO Y REGLAS:
// 1. Regla Inmutable SSoT 1.1: NUNCA responder con mensajes de chat hacia un REPEATER.
//    Los repetidores son infraestructura de red y no poseen interfaz de chat.
// 2. Comandos reconocidos: /time, /date, /datetime, /ping, /clima, /weather, /nodes, /help
// 3. Fallback: Eco público formatado con indicación de emisor para pruebas de cobertura RF.
// ==============================================================================

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = String(msg.text || '').trim();
  if (!rawText) {
    continue;
  }

  // REGLA SSoT: Ignorar repetidores para chat
  const role = String(msg.role || '').toUpperCase();
  if (role === 'REPEATER' || role === 'ROUTER') {
    continue;
  }

  const lower = rawText.toLowerCase();
  const senderName = msg.sender_name || msg.sender_id || 'Nodo';
  const now = new Date();
  let replyText = '';

  if (lower === '/time') {
    replyText = `⏰ Hora actual: ${now.toISOString().substring(11, 19)} UTC`;
  } else if (lower === '/date') {
    replyText = `📅 Fecha actual: ${now.toISOString().split('T')[0]}`;
  } else if (lower === '/datetime') {
    replyText = `📅⏰ Fecha y Hora: ${now.toISOString().replace('T', ' ').substring(0, 19)} UTC`;
  } else if (lower === '/ping') {
    replyText = `🏓 Pong desde n8n Bridge! (Nodo: ${senderName})`;
  } else if (lower === '/clima' || lower === '/weather') {
    replyText = `🌤️ Consulta meteorológica: Lehigh Acres, FL recibe reporte automático cada 6h (00:00, 06:00, 12:00, 18:00 UTC).`;
  } else if (lower === '/help') {
    replyText = `📖 Comandos: /time (UTC) | /date | /clima | /ping | /status | /admin`;
  } else {
    replyText = `[Eco Pub] ${senderName}: "${rawText}"`;
  }

  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_pub_${Date.now()}`,
      target: 'broadcast',
      to: 'broadcast',
      channel_index: 0,
      channel_idx: 0,
      text: replyText
    }
  });
}

return results;

// ==============================================================================
// N8N NODE: Procesador de Canales Secundarios Cifrados (Canales 1..7)
// ==============================================================================
// CONTRATO Y REGLAS:
// 1. Regla Inmutable SSoT 1.1: NUNCA responder con mensajes de chat hacia un REPEATER.
// 2. Mantiene la comunicación confinada al índice de canal de origen (ch_idx).
// ==============================================================================

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = String(msg.text || '').trim();
  if (!rawText) {
    continue;
  }

  // REGLA SSoT: Prohibido chat con repetidores
  const role = String(msg.role || '').toUpperCase();
  if (role === 'REPEATER' || role === 'ROUTER') {
    continue;
  }

  const senderName = msg.sender_name || msg.sender_id || 'Nodo';
  const chIdx = Number(msg.channel_index !== undefined ? msg.channel_index : (msg.channel_idx || 1));

  const replyText = `[Eco Ch ${chIdx}] ${senderName}: "${rawText}"`;

  results.push({
    json: {
      topic: 'meshcore/tx',
      request_id: `n8n_chan_${Date.now()}`,
      target: 'broadcast',
      to: 'broadcast',
      channel_index: chIdx,
      channel_idx: chIdx,
      text: replyText
    }
  });
}

return results;

// ==============================================================================
// N8N NODE: Procesador de Mensajes Directos (DM), Comandos Admin y Repetidores
// ==============================================================================
// CONTRATO Y REGLAS:
// 1. Regla Inmutable SSoT 1.1: NUNCA responder chat DM hacia un REPEATER.
//    La interacción con repetidores es estrictamente administrativa vía meshcore/admin/repeater.
// 2. Whitelist de Administradores: Solo nodos autorizados pueden ejecutar /admin.
// 3. Comandos Administrativos soportados:
//    - /status: Estado operativo y métricas de radio/enlace.
//    - /admin ping <target_node>: Disparo de Ping (Hop 0) hacia repetidor.
//    - /admin trace <target_node>: Solicitud de Traceroute hacia nodo remoto.
//    - /admin repeater <target_node> <cmd>: Comando remoto a repetidor.
//    - /admin [get_config|list_nodes|set_name|set_power|reboot]: Comandos locales al bridge.
// ==============================================================================

// Whitelist de Administradores basada ESTRICTAMENTE en Claves Públicas / IDs canónicos (MT08)
// NUNCA incluir nombres de nodos en la whitelist para prevenir suplantación de identidad.
const ADMIN_WHITELIST = [
  '8f3a12bc',
  'feedfacecafe0001'
];

const results = [];

for (const item of $input.all()) {
  const msg = item.json;
  const rawText = String(msg.text || '').trim();
  if (!rawText) {
    continue;
  }

  const senderId = String(msg.sender || msg.sender_id || 'unknown').trim();
  const senderName = String(msg.sender_name || senderId).trim();
  const role = String(msg.role || '').toUpperCase();

  // REGLA SSoT: Prohibido enviar chat a repetidores
  const isRepeater = (role === 'REPEATER' || role === 'ROUTER');

  const lower = rawText.toLowerCase();
  const isAdmin = ADMIN_WHITELIST.map(k => k.toLowerCase()).includes(senderId.toLowerCase());

  // 1. Comando /status (Consulta de vivacidad y calidad de enlace)
  if (lower === '/status') {
    if (isRepeater) continue; // Repetidores no reciben respuestas de chat
    const rssiVal = msg.last_rssi !== undefined ? msg.last_rssi : (msg.rssi || null);
    const snrVal = msg.last_snr !== undefined ? msg.last_snr : (msg.snr || null);
    const rssiInfo = rssiVal !== null ? ` | RSSI: ${rssiVal} dBm` : '';
    const snrInfo = snrVal !== null ? ` | SNR: ${snrVal} dB` : '';
    const replyText = `[Status MeshCore v3.0]\nBridge: Online\nNodo: ${senderName}${rssiInfo}${snrInfo}\nHora: ${new Date().toISOString().substring(11, 19)} UTC`;

    results.push({
      json: {
        topic: 'meshcore/tx',
        request_id: `n8n_status_${Date.now()}`,
        target: senderId,
        to: senderId,
        channel_index: 0,
        channel_idx: 0,
        text: replyText
      }
    });
    continue;
  }

  // 2. Comandos Administrativos (/admin)
  if (lower.startsWith('/admin')) {
    if (!isAdmin) {
      if (!isRepeater) {
        results.push({
          json: {
            topic: 'meshcore/tx',
            request_id: `n8n_denied_${Date.now()}`,
            target: senderId,
            to: senderId,
            channel_index: 0,
            channel_idx: 0,
            text: '⛔ Acceso denegado: Nodo no autorizado para comandos administrativos.'
          }
        });
      }
      continue;
    }

    const parts = rawText.split(' ').filter(p => p.length > 0);
    const subCmd = (parts[1] || '').toLowerCase();

    // Caso A: Ping (Hop 0) hacia Repetidor (/admin ping <node_id>)
    if (subCmd === 'ping' && parts[2]) {
      const targetRep = parts[2].trim();
      results.push({
        json: {
          topic: `meshcore/admin/repeater/${targetRep}/cmd`,
          request_id: `n8n_ping0_${Date.now()}`,
          action: 'ping_zero',
          target_node: targetRep
        }
      });
      if (!isRepeater) {
        results.push({
          json: {
            topic: 'meshcore/tx',
            request_id: `n8n_ack_ping_${Date.now()}`,
            target: senderId,
            to: senderId,
            text: `🎯 Disparando Ping (Hop 0) a repetidor ${targetRep}...`
          }
        });
      }
      continue;
    }

    // Caso B: Traceroute hacia Nodo (/admin trace <node_id>)
    if (subCmd === 'trace' && parts[2]) {
      const targetNode = parts[2].trim();
      results.push({
        json: {
          topic: `meshcore/admin/repeater/${targetNode}/cmd`,
          request_id: `n8n_trace_${Date.now()}`,
          action: 'traceroute',
          target_node: targetNode
        }
      });
      if (!isRepeater) {
        results.push({
          json: {
            topic: 'meshcore/tx',
            request_id: `n8n_ack_trace_${Date.now()}`,
            target: senderId,
            to: senderId,
            text: `🗺️ Ejecutando Traceroute hacia ${targetNode}...`
          }
        });
      }
      continue;
    }

    // Caso C: Comandos Genéricos a Repetidores (/admin repeater <node_id> <cmd>)
    if (subCmd === 'repeater' && parts[2] && parts[3]) {
      const targetRepeater = parts[2].trim();
      const repCmd = parts.slice(3).join(' ');
      results.push({
        json: {
          topic: `meshcore/admin/repeater/${targetRepeater}/cmd`,
          request_id: `n8n_rep_${Date.now()}`,
          action: repCmd,
          target_node: targetRepeater
        }
      });
      if (!isRepeater) {
        results.push({
          json: {
            topic: 'meshcore/tx',
            request_id: `n8n_ack_${Date.now()}`,
            target: senderId,
            to: senderId,
            text: `📡 Enviando comando "${repCmd}" a repetidor ${targetRepeater}...`
          }
        });
      }
      continue;
    }

    // Caso D: Comandos Locales al Bridge
    let actionName = null;
    let ackNotice = '';
    let extraData = {};

    if (subCmd === 'get_config' || subCmd === 'config') {
      actionName = 'get_config';
      ackNotice = '⚙️ Consultando configuración del nodo...';
    } else if (subCmd === 'list_nodes' || subCmd === 'nodes') {
      actionName = 'list_nodes';
      ackNotice = '📖 Consultando registro de nodos activos...';
    } else if (subCmd === 'set_name' && parts[2]) {
      actionName = 'set_name';
      extraData.name = parts.slice(2).join(' ');
      ackNotice = `✏️ Cambiando nombre a: ${extraData.name}`;
    } else if (subCmd === 'set_power' && parts[2]) {
      actionName = 'set_tx_power';
      extraData.power = parseInt(parts[2], 10);
      ackNotice = `📶 Ajustando potencia TX a: ${extraData.power} dBm`;
    } else if (subCmd === 'reboot') {
      actionName = 'reboot';
      ackNotice = '🔄 Reiniciando radio local...';
    } else {
      ackNotice = '❓ Comando no reconocido. Uso: /admin [config|nodes|ping <id>|trace <id>|set_name <n>|set_power <p>|repeater <id> <cmd>]';
    }

    if (!isRepeater) {
      results.push({
        json: {
          topic: 'meshcore/tx',
          request_id: `n8n_adm_ack_${Date.now()}`,
          target: senderId,
          to: senderId,
          channel_index: 0,
          channel_idx: 0,
          text: ackNotice
        }
      });
    }

    if (actionName) {
      results.push({
        json: {
          topic: 'meshcore/admin/cmd',
          request_id: `n8n_adm_${Date.now()}`,
          action: actionName,
          ...extraData
        }
      });
    }
    continue;
  }

  // 3. Eco DM (Mensajería Privada directa)
  // SSoT: Si es un repetidor, jamás responder con eco
  if (!isRepeater) {
    results.push({
      json: {
        topic: 'meshcore/tx',
        request_id: `n8n_dm_${Date.now()}`,
        target: senderId,
        to: senderId,
        channel_index: 0,
        channel_idx: 0,
        text: `[Eco DM] Recibido: "${rawText}"`
      }
    });
  }
}

return results;

// ==============================================================================
// N8N NODE: Procesador de Telemetría Ambiental y Sensores CayenneLPP / MeshCore
// ==============================================================================
// CONTRATO Y ESQUEMA SSoT:
// - Consume lecturas normalizadas del bridge (batería, voltaje, solar, temp, hum, press, GPS).
// - Detecta umbrales críticos de operación para alertas operativas tempranas.
// ==============================================================================

const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const sender = data.sender || data.sender_id || 'unknown';
  const role = data.role || 'CLIENT';
  const temp = data.temperature_c !== undefined ? data.temperature_c : null;
  const hum = data.humidity_pct !== undefined ? data.humidity_pct : null;
  const press = data.pressure_hpa !== undefined ? data.pressure_hpa : null;
  const batt = data.battery_pct !== undefined ? data.battery_pct : (data.battery !== undefined ? data.battery : null);
  const volt = data.voltage_v !== undefined ? data.voltage_v : null;
  const solar = data.solar_v !== undefined ? data.solar_v : null;
  const lat = data.latitude !== undefined ? data.latitude : null;
  const lon = data.longitude !== undefined ? data.longitude : null;
  const alt = data.altitude_m !== undefined ? data.altitude_m : null;
  const airtime = data.airtime_ms !== undefined ? data.airtime_ms : null;
  const duty = data.duty_cycle_pct !== undefined ? data.duty_cycle_pct : null;

  let isAlert = false;
  let alertMsg = '';

  // Umbral Crítico 1: Batería baja (< 20%)
  if (batt !== null && batt < 20) {
    isAlert = true;
    alertMsg += `⚠️ Batería baja (${batt}%) en nodo ${sender} [${role}]. `;
  }

  // Umbral Crítico 2: Temperatura extrema (> 45.0°C)
  if (temp !== null && temp > 45.0) {
    isAlert = true;
    alertMsg += `🔥 Temperatura crítica (${temp}°C) en nodo ${sender} [${role}]. `;
  }

  // Umbral Crítico 3: Duty Cycle LoRa elevado (> 0.8% por hora)
  if (duty !== null && duty > 0.8) {
    isAlert = true;
    alertMsg += `📻 Duty cycle LoRa elevado (${duty}%) en nodo ${sender}. `;
  }

  results.push({
    json: {
      event_type: 'telemetry_processed',
      sender: sender,
      role: role,
      temperature_c: temp,
      humidity_pct: hum,
      pressure_hpa: press,
      battery_pct: batt,
      voltage_v: volt,
      solar_v: solar,
      gps: (lat !== null && lon !== null) ? { latitude: lat, longitude: lon, altitude_m: alt } : null,
      airtime_ms: airtime,
      duty_cycle_pct: duty,
      is_alert: isAlert,
      alert_text: alertMsg.trim(),
      timestamp: new Date().toISOString()
    }
  });
}

return results;

// ==============================================================================
// N8N NODE: Procesador de Anuncios de Nodos (Node Discovery / Adverts)
// ==============================================================================
// CONTRATO Y ESQUEMA SSoT:
// - Registra la presencia y topología de nodos en la malla LoRa.
// - Clasifica nodos por rol canónico (CLIENT, REPEATER, ROOM, SENSOR).
// ==============================================================================

const results = [];

for (const item of $input.all()) {
  const data = item.json;
  const senderId = data.sender || data.sender_id || 'unknown';
  const senderName = data.sender_name || data.adv_name || data.name || senderId;
  const role = String(data.role || 'CLIENT').toUpperCase();
  const hops = data.hops !== undefined ? data.hops : (data.hop_count || 0);

  results.push({
    json: {
      event_type: 'node_discovered',
      node_id: senderId,
      node_name: senderName,
      role: role,
      hops: hops,
      battery_pct: data.battery_pct !== undefined ? data.battery_pct : null,
      hardware_board: data.hardware_board || null,
      discovered_at: new Date().toISOString()
    }
  });
}

return results;

