      route_type_id: data.route_type_id !== undefined ? data.route_type_id : null,
      payload_type_id: data.payload_type_id !== undefined ? data.payload_type_id : null,
      bytes: data.byte_length || data.bytes || 0,
      captured_at: new Date().toISOString()
    }
  });
}

return results;
